package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;

public class OfflineVoicesTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier condition,String message)throws Exception{long until=SystemClock.elapsedRealtime()+40000;while(SystemClock.elapsedRealtime()<until){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(condition.getAsBoolean()));if(ready.get())return;Thread.sleep(50);}throw new AssertionError(message);}
    void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(350);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    void shell(String command)throws Exception{try(InputStream input=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){byte[] buffer=new byte[256];while(input.read(buffer)!=-1){}}}
    public void onCreate(Bundle state){super.onCreate(state);start();}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();SharedPreferences prefs=context.getSharedPreferences("reading_settings",0);Map<String,?> backup=new HashMap<>(prefs.getAll());LocaleManager locales=context.getSystemService(LocaleManager.class);String locale=locales.getApplicationLocales().toLanguageTags();OfflineVoicesActivity manager=null;MainActivity reader=null;ModelManagerActivity my=null;boolean passed=false;try{
        check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for offline voice test");reader=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","voice_management_qa").putExtra("book_name","离线语音验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity book=reader;await(()->book.offlineReady&&book.system.initialized,"reader engines not ready");ui(()->{book.text="The little horse is reading a book in the garden. Today the weather is beautiful and the flowers are blooming.";book.chapters=MainActivity.parse(book.text);book.position=0;book.readingLanguage="ja";book.systemVoiceKey=book.system.offlineVoice("ja","").key;book.showPosition(true);prefs.edit().putString("readingLanguage","ja").putString("systemVoiceKey",book.systemVoiceKey).apply();});
        my=(ModelManagerActivity)startActivitySync(new Intent(context,ModelManagerActivity.class).putExtra("home",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ModelManagerActivity home=my;ActivityMonitor entry=addMonitor(OfflineVoicesActivity.class.getName(),null,false);ui(()->home.body.getChildAt(2).performClick());manager=(OfflineVoicesActivity)waitForMonitorWithTimeout(entry,10000);removeMonitor(entry);check(manager!=null,"My offline voice entry failed");final OfflineVoicesActivity a=manager;await(()->a.system!=null&&a.system.initialized,"voice catalogue not ready");ui(()->{check(a.headers.size()==15,"language cards missing");check(a.items("zh").stream().filter(item->item.option==null).count()==4,"built-in voices missing");for(String language:new String[]{"zh","en","ja"}){check(!a.items(language).isEmpty(),"missing real offline voices for "+language);for(OfflineVoicesActivity.Item item:a.items(language))if(item.option!=null)check(SystemSpeaker.offlineUsable(item.option.voice)&&item.option.voice.getLocale().getLanguage().equals(language),"network/uninstalled/wrong-language voice listed");}});screenshot("offline-voices-overview.png");
        ui(()->{((android.view.View)a.headers.get("ja").getParent().getParent()).performClick();check(!a.voiceRows.isEmpty(),"Japanese voice list empty");});screenshot("offline-voices-japanese.png");OfflineVoicesActivity.Item japanese=a.items("ja").get(a.items("ja").size()-1);String oldGlobal=prefs.getString("systemVoiceKey","");ui(()->{a.voiceRows.get(japanese.key).container.performClick();check(a.previewKey.isEmpty()&&!a.guard.held,"selection started preview");check(prefs.getString("japaneseVoiceKey","").equals(japanese.option.key),"Japanese selection not saved");a.voiceRows.get(japanese.key).play.performClick();});await(()->a.previewStarted&&a.previewKey.equals(japanese.key),"actual Japanese preview did not start");ui(()->{check(a.voiceRows.get(japanese.key).play.getText().toString().equals("Ⅱ"),"pause icon missing");a.voiceRows.get(japanese.key).play.performClick();check(a.previewKey.isEmpty()&&!a.guard.held,"Japanese pause failed");});
        ui(()->{String global=prefs.getString("systemVoiceKey","");OfflineVoicesActivity.Item english=a.items("en").get(0);a.select(english);check(prefs.getString("englishVoiceKey","").equals(english.option.key),"English preference missing");check(prefs.getString("systemVoiceKey","").equals(global),"English selection replaced active Japanese voice");a.expanded="en";a.render();a.voiceRows.get(english.key).play.performClick();});await(()->a.previewStarted,"actual English preview failed");ui(()->{a.stopPreview();a.expanded="zh";a.render();a.voiceRows.get("local:2015").container.performClick();check(prefs.getString("chineseVoiceKey","x").isEmpty()&&prefs.getInt("offlineVoice",0)==2015,"built-in selection not stored");a.voiceRows.get("local:2015").play.performClick();});await(()->a.previewStarted,"built-in preview failed");ui(()->{a.voiceRows.get("local:2015").play.performClick();check(a.previewKey.isEmpty()&&!a.guard.held,"built-in pause failed");});
        ui(()->{ArrayList<SystemSpeaker.Option> options=new ArrayList<>(a.system.options);Map<String,String> engines=new LinkedHashMap<>(a.system.engineLabels);a.system.options.clear();a.system.engineLabels.clear();a.expanded="ja";a.render();check(a.items("ja").isEmpty()&&a.voiceRows.isEmpty(),"missing-language state shows unavailable voices");check(a.items("zh").size()==4,"no-system state lost built-in voices");a.system.options.addAll(options);a.system.engineLabels.putAll(engines);a.render();});
        SystemSpeaker before=a.system;ui(()->{a.preview(japanese);a.engineButtons.get("com.google.android.tts:ja:delete").performClick();});await(()->!a.visible,"Google voice manager did not open");check(a.previewKey.isEmpty()&&!a.guard.held,"leaving page kept preview/focus");shell("input keyevent 4");await(()->a.visible&&a.system!=null&&a.system.initialized&&a.system!=before,"voice status did not refresh after return");ui(()->{check(!a.items("ja").isEmpty(),"return lost installed Japanese voices");a.select(japanese);a.finish();home.finish();});manager=null;my=null;await(()->book.readerVisible,"reader not resumed");ui(()->{book.refreshManagedVoice();check(book.systemVoiceKey.equals(japanese.option.key),"existing reader did not adopt saved voice");book.startReading();});await(()->book.playing&&book.focusGeneration==book.generation&&book.latestStatus.contains("Google Translate"),"selected Japanese voice not used for reading");ui(()->{book.stop();book.finish();});reader=null;
        ui(()->locales.setApplicationLocales(LocaleList.forLanguageTags("en")));Thread.sleep(300);manager=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity en=manager;await(()->en.system!=null&&en.system.initialized,"English manager not ready");screenshot("offline-voices-en.png");ui(()->{check(en.getString(R.string.speech_title).equals("Offline voices"),"English resources missing");en.finish();locales.setApplicationLocales(LocaleList.forLanguageTags("ar"));});manager=null;Thread.sleep(300);manager=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity ar=manager;await(()->ar.system!=null&&ar.system.initialized&&ar.root.getLayoutDirection()==android.view.View.LAYOUT_DIRECTION_RTL,"Arabic RTL not ready");screenshot("offline-voices-ar.png");result.putString("result","PASS: My entry; zh/en/ja real offline catalogue; built-in voices; filters missing/network data; select without preview; per-language preferences; actual Japanese/English/built-in previews and pause; missing-system state; real Google voice package page; stop preview on leave; refresh on return; existing reader uses saved Japanese voice; English/Arabic RTL");passed=true;
    }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(manager!=null){final OfflineVoicesActivity a=manager;ui(a::finish);}if(my!=null){final ModelManagerActivity a=my;ui(a::finish);}if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}SharedPreferences.Editor restore=prefs.edit().clear();for(Map.Entry<String,?> entry:backup.entrySet()){String key=entry.getKey();Object value=entry.getValue();if(value instanceof String)restore.putString(key,(String)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else if(value instanceof Long)restore.putLong(key,(Long)value);else if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Float)restore.putFloat(key,(Float)value);}restore.commit();ui(()->locales.setApplicationLocales(LocaleList.forLanguageTags(locale)));context.getSharedPreferences("reader_voice_management_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_voice_management_qa.txt.position").delete();}finish(passed?-1:0,result);}
}
